fill-={p for p in fill if g[p[0]][p[1]]!=8}
# full bars for rows/cols with consecutive given runs (>=2)
def has_run(vals):
    s=sorted(vals); return any(b-a==1 for a,b in zip(s,s[1:]))
if has_run(r for r,c in givens if c0<=c<=c1):
    for r in range(r0,r1+1): fill.add((r,c0)) # placeholder no
for c in range(c0,c1+1):
    col=[r for (r,cc) in givens if cc==c]
    if has_run(col):
        for r in range(r0,r1+1): fill.add((r,c))
